using System.Collections;
using System.Reflection;
using System.Text.Json;
using CombatSolver.Engine.InCombat.Simulation;
using Godot;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Nodes;
using STS2RitsuLib.Models.Capabilities;

namespace CombatSolver;
internal sealed partial class UnattendedTestRunner
{
    private sealed class TaskAudienceCapability : AbstractModel, IModelCapability, IModelCapabilityHookListener
    {
        public TaskAudienceCapability() { }
        internal Player? HealingPlayer;
        internal int Calls;
        public override bool ShouldReceiveCombatHooks => false;
        public string CapabilityId => "task-cost-hook-audience";
        public AbstractModel? Owner { get; private set; }
        public void Attach(AbstractModel owner, bool isInternal = false) => Owner = owner;
        public void Detach(bool isInternal = false) => Owner = null;
        public bool ShouldReceiveOwnerHooks
        {
            get { Calls++; if (Calls == 1) HealingPlayer!.Creature.HealInternal(2m); return false; }
        }
        public int OwnerHookOrder => 0;
    }

    private static void PrepareTaskCostAudienceCapability()
    {
        string path = UnattendedTestFiles.GlobalPath(UnattendedTestFiles.RequestUri);
        if (!File.Exists(path)) return;
        using var document = JsonDocument.Parse(File.ReadAllText(path));
        if (!document.RootElement.TryGetProperty("scenarioId", out var scenario)
            || scenario.GetString() != "TASK-COST-HOOK-AUDIENCE") return;
        ModelCapabilities.EnsureInitialized();
        ModelCapabilityRegistry.Register<TaskAudienceCapability>("task-cost-hook-audience",
            () => (TaskAudienceCapability)ModelDb.All.OfType<TaskAudienceCapability>().Single().MutableClone());
    }

    private async Task AssertTaskCostHookAudienceAsync(CombatState live, Player player)
    {
        SetStage("task_cost_hook_audience");
        for (int i = 0; i < 3; i++)
            await NGame.Instance!.ToSignal(NGame.Instance.GetTree(), SceneTree.SignalName.ProcessFrame);
        var root = CombatRootSnapshot.Capture(live);
        var parent = root.ForkSimulator();
        string Stamp(CombatPredictionSimulator sim) => DescribeContinuationContractState(sim, root, player);
        string parentBefore = Stamp(parent), liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        const BindingFlags flags = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static;
        var owner = ModelDb.Card<DefendRegent>();
        var host = ModelCapabilities.Get(owner);
        var attachedField = typeof(ModelCapabilitySet).GetField("_attachedSnapshot", flags)!;
        var candidateField = typeof(ModelCapabilitySet).GetField("_ownerHookCandidateSnapshot", flags)!;
        var list = (ICollection)typeof(ModelCapabilitySet).GetField("_capabilities", flags)!.GetValue(host)!;
        var unknown = (ICollection)typeof(ModelCapabilitySet).GetField("_unknownEntries", flags)!.GetValue(host)!;
        if (list.Count != 0 || unknown.Count != 0) throw new InvalidOperationException("Nonempty baseline host.");
        object? attachedBefore = attachedField.GetValue(host), candidatesBefore = candidateField.GetValue(host);
        Type listeners = typeof(ModelCapabilities).Assembly.GetType("STS2RitsuLib.Models.Capabilities.ModelCapabilityHookListeners")!;
        var markers = listeners.GetField("OwnersWithoutHookCapabilities", flags)!.GetValue(null)!;
        object?[] markerArgs = [owner, null];
        bool hadMarker = (bool)markers.GetType().GetMethod("TryGetValue", flags)!.Invoke(markers, markerArgs)!;
        var capability = (TaskAudienceCapability)ModelDb.All.OfType<TaskAudienceCapability>().Single().MutableClone();
        capability.HealingPlayer = player;
        bool accepted = false, normalInvalidation = false;
        int hpBefore = player.Creature.CurrentHp, hpAfter = hpBefore;
        try
        {
            host.Apply(capability);
            typeof(ModelCapabilitySet).GetMethod("GetOwnerHookCandidateSnapshot", flags)!.Invoke(host, null);
            if (!host.Remove(capability)) throw new InvalidOperationException("Native removal failed.");
            normalInvalidation = attachedField.GetValue(host) == null && candidateField.GetValue(host) == null;
            if (!normalInvalidation || list.Count != 0 || capability.Calls != 0)
                throw new InvalidOperationException("Normal API did not invalidate snapshots without invoking predicates.");
            capability.Attach(owner, true);
            candidateField.SetValue(host, new IModelCapability[] { capability });
            listeners.GetMethod("InvalidateOwnerHookCapabilityCache", flags)!.Invoke(null, [owner]);
            PredictionRitsuCapabilityAudit.Validate(); accepted = true;
            var expanded = (IEnumerable<AbstractModel>)listeners.GetMethod("ExpandOwnerHookListeners", flags)!.Invoke(null, [new AbstractModel[] { owner }])!;
            var result = expanded.ToArray(); hpAfter = player.Creature.CurrentHp;
            if (result.Length != 1 || !ReferenceEquals(result[0], owner) || capability.Calls != 1 || hpAfter != hpBefore + 2)
                throw new InvalidOperationException("Cached false predicate did not reproduce unchanged audience with HP side effect.");
            if (Stamp(parent) != parentBefore || Stamp(parent.Fork()) != parentBefore)
                throw new InvalidOperationException("Native probe changed frozen parent or Fork state/history/RNG.");
        }
        finally
        {
            capability.Detach(true);
            attachedField.SetValue(host, attachedBefore); candidateField.SetValue(host, candidatesBefore);
            listeners.GetMethod("InvalidateOwnerHookCapabilityCache", flags)!.Invoke(null, [owner]);
            if (hadMarker) markers.GetType().GetMethod("Set", flags)!.Invoke(markers, [owner, markerArgs[1]]);
        }
        File.WriteAllText("/home/ltlly/Code/nmslmod/CombatSolver-common-state-cost-20261005/.local/tool-tasks/cost-hook-audience-proof-20261008/native-details.json",
            JsonSerializer.Serialize(new { normalApiInvalidatesBothSnapshots = normalInvalidation, reflectedCacheMutation = true,
                activeCount = list.Count, unknownCount = unknown.Count, cachedCandidateCount = 1,
                existingGuardAccepted = accepted, unchangedAudience = true, falsePredicateCalls = capability.Calls,
                hpBefore, hpAfter, parentAndForkFullStateHistoryRngUnchanged = true,
                wholeCertificate = false, productionPrunes = 0, searchStarted = false }));
        _completedChecks.Add("TaskCostHookAudience:NormalApiInvalidates:ReflectedCacheCounterexample:FalsePredicateHeal:AudienceUnchanged:ParentForkIsolated:NoWholeCertificate");
    }
}

