using System;
using System.Collections.Generic;
using MegaCrit.Sts2.Core.Models;
using STS2RitsuLib.Utils;

namespace STS2RitsuLib.Models.Capabilities;

internal static class ModelCapabilityHookListeners
{
	private readonly record struct OwnerHookCapabilityEntry(IModelCapability Capability, AbstractModel Model, int OwnerHookOrder, int Index);

	private readonly struct OwnerHookCapabilitySnapshot
	{
		private readonly OwnerHookCapabilityEntry? _single;

		private readonly List<OwnerHookCapabilityEntry>? _multiple;

		public int Count => _multiple?.Count ?? (_single.HasValue ? 1 : 0);

		public OwnerHookCapabilityEntry this[int index]
		{
			get
			{
				if (_multiple != null)
				{
					return _multiple[index];
				}
				if (index == 0)
				{
					OwnerHookCapabilityEntry? single = _single;
					if (single.HasValue)
					{
						return single.GetValueOrDefault();
					}
				}
				throw new ArgumentOutOfRangeException("index");
			}
		}

		public OwnerHookCapabilitySnapshot(OwnerHookCapabilityEntry? single)
		{
			_single = single;
			_multiple = null;
		}

		public OwnerHookCapabilitySnapshot(List<OwnerHookCapabilityEntry> multiple)
		{
			_single = null;
			_multiple = multiple;
		}
	}

	private static readonly object NoOwnerHookCapabilitiesMarker = new object();

	private static readonly AttachedState<AbstractModel, object> OwnersWithoutHookCapabilities = new AttachedState<AbstractModel, object>((Func<object>)null);

	internal static void InvalidateDefaultCapabilitySourceCache()
	{
		OwnersWithoutHookCapabilities.Clear();
	}

	internal static void InvalidateOwnerHookCapabilityCache(AbstractModel owner)
	{
		OwnersWithoutHookCapabilities.Remove(owner);
	}

	internal static IEnumerable<AbstractModel> ExpandOwnerHookListeners(IEnumerable<AbstractModel> owners)
	{
		object obj = default(object);
		foreach (AbstractModel owner in owners)
		{
			if (owner is IModelCapability modelCapability)
			{
				if (modelCapability.Owner == null)
				{
					yield return owner;
				}
				continue;
			}
			if (OwnersWithoutHookCapabilities.TryGetValue(owner, ref obj))
			{
				yield return owner;
				continue;
			}
			OwnerHookCapabilitySnapshot capabilities = GetOwnerHookCapabilities(owner);
			int index;
			for (index = 0; index < capabilities.Count && capabilities[index].OwnerHookOrder < 0; index++)
			{
				if (TryGetStillAttachedModel(capabilities[index], owner, out AbstractModel model))
				{
					yield return model;
				}
			}
			yield return owner;
			for (; index < capabilities.Count; index++)
			{
				if (TryGetStillAttachedModel(capabilities[index], owner, out AbstractModel model2))
				{
					yield return model2;
				}
			}
		}
	}

	private static OwnerHookCapabilitySnapshot GetOwnerHookCapabilities(AbstractModel owner)
	{
		if (!ModelCapabilities.TryGet(owner, out ModelCapabilitySet collection))
		{
			if (!ModelCapabilityDefaults.HasDefaultCapabilitySource(owner))
			{
				MarkOwnerWithoutHookCapabilities(owner);
				return default(OwnerHookCapabilitySnapshot);
			}
			collection = ModelCapabilities.Get(owner);
		}
		IModelCapability[] ownerHookCandidateSnapshot = collection.GetOwnerHookCandidateSnapshot();
		if (ownerHookCandidateSnapshot.Length == 0)
		{
			MarkOwnerWithoutHookCapabilities(owner);
			return default(OwnerHookCapabilitySnapshot);
		}
		OwnerHookCapabilityEntry? single = null;
		List<OwnerHookCapabilityEntry> list = null;
		for (int i = 0; i < ownerHookCandidateSnapshot.Length; i++)
		{
			IModelCapability modelCapability = ownerHookCandidateSnapshot[i];
			if (!(modelCapability is IModelCapabilityHookListener { ShouldReceiveOwnerHooks: not false } modelCapabilityHookListener))
			{
				continue;
			}
			AbstractModel val = (AbstractModel)((modelCapabilityHookListener is AbstractModel) ? modelCapabilityHookListener : null);
			if (val == null)
			{
				continue;
			}
			OwnerHookCapabilityEntry ownerHookCapabilityEntry = new OwnerHookCapabilityEntry(modelCapability, val, modelCapabilityHookListener.OwnerHookOrder, i);
			if (!single.HasValue)
			{
				single = ownerHookCapabilityEntry;
				continue;
			}
			if (list == null)
			{
				list = new List<OwnerHookCapabilityEntry>(ownerHookCandidateSnapshot.Length) { single.Value };
			}
			list.Add(ownerHookCapabilityEntry);
		}
		if (list == null)
		{
			return new OwnerHookCapabilitySnapshot(single);
		}
		list.Sort(delegate(OwnerHookCapabilityEntry left, OwnerHookCapabilityEntry right)
		{
			int num = left.OwnerHookOrder.CompareTo(right.OwnerHookOrder);
			return (num == 0) ? left.Index.CompareTo(right.Index) : num;
		});
		return new OwnerHookCapabilitySnapshot(list);
	}

	private static void MarkOwnerWithoutHookCapabilities(AbstractModel owner)
	{
		OwnersWithoutHookCapabilities.GetOrAdd(owner, (Func<AbstractModel, object>)((AbstractModel _) => NoOwnerHookCapabilitiesMarker));
	}

	private static bool TryGetStillAttachedModel(OwnerHookCapabilityEntry entry, AbstractModel owner, out AbstractModel model)
	{
		model = entry.Model;
		return entry.Capability.Owner == owner;
	}
}
