using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Linq;
using MegaCrit.Sts2.Core.Models;

namespace STS2RitsuLib.Models.Capabilities;

/// <summary>
///     <para xml:lang="en">Represents the mutable capability set attached to one model instance.</para>
///     <para xml:lang="zh-CN">表示附加到单个模型实例的可变能力集合。</para>
/// </summary>
public sealed class ModelCapabilitySet
{
	private readonly record struct CapabilityLoadItem(IModelCapability Capability, bool IsDefault);

	private sealed class CapabilityLoadState
	{
		private readonly Dictionary<string, Queue<CapabilityLoadItem>> _queues = new Dictionary<string, Queue<CapabilityLoadItem>>(StringComparer.Ordinal);

		private readonly List<CapabilityLoadItem> _remaining = new List<CapabilityLoadItem>();

		public void Add(IModelCapability capability, bool isDefault)
		{
			CapabilityLoadItem item = new CapabilityLoadItem(capability, isDefault);
			_remaining.Add(item);
			if (!_queues.TryGetValue(capability.CapabilityId, out Queue<CapabilityLoadItem> value))
			{
				value = new Queue<CapabilityLoadItem>();
				_queues[capability.CapabilityId] = value;
			}
			value.Enqueue(item);
		}

		public bool TryTake(string capabilityId, out CapabilityLoadItem item)
		{
			item = default(CapabilityLoadItem);
			if (!_queues.TryGetValue(capabilityId, out Queue<CapabilityLoadItem> value) || value.Count == 0)
			{
				return false;
			}
			item = value.Dequeue();
			IModelCapability capability = item.Capability;
			int num = _remaining.FindIndex((CapabilityLoadItem candidate) => candidate.Capability == capability);
			if (num >= 0)
			{
				_remaining.RemoveAt(num);
			}
			return true;
		}

		public IReadOnlyList<CapabilityLoadItem> TakeRemaining()
		{
			CapabilityLoadItem[] result = _remaining.ToArray();
			_remaining.Clear();
			foreach (Queue<CapabilityLoadItem> value in _queues.Values)
			{
				value.Clear();
			}
			return result;
		}
	}

	private const string LoadSurface = "model-capability-load";

	private readonly List<IModelCapability> _capabilities = new List<IModelCapability>();

	private readonly HashSet<IModelCapability> _defaultCapabilities = new HashSet<IModelCapability>(ReferenceEqualityComparer.Instance);

	private readonly ReadOnlyCollection<IModelCapability> _readOnlyCapabilities;

	private readonly List<ModelCapabilitySaveEntry> _unknownEntries = new List<ModelCapabilitySaveEntry>();

	private IModelCapability[]? _attachedSnapshot;

	private IModelCapability[]? _ownerHookCandidateSnapshot;

	/// <summary>
	///     <para xml:lang="en">Gets the owning model.</para>
	///     <para xml:lang="zh-CN">获取所属模型。</para>
	/// </summary>
	public AbstractModel Owner { get; }

	/// <summary>
	///     <para xml:lang="en">Gets all attached capabilities in execution order.</para>
	///     <para xml:lang="zh-CN">获取按执行顺序排列的所有已附加能力。</para>
	/// </summary>
	public IReadOnlyList<IModelCapability> All => _readOnlyCapabilities;

	/// <summary>
	///     <para xml:lang="en">Gets all attached capabilities in execution order.</para>
	///     <para xml:lang="zh-CN">获取按执行顺序排列的所有已附加能力。</para>
	/// </summary>
	public IReadOnlyList<IModelCapability> Attached => _readOnlyCapabilities;

	internal bool IsDirty { get; private set; }

	/// <summary>
	///     <para xml:lang="en">Gets the number of currently attached capabilities.</para>
	///     <para xml:lang="zh-CN">获取当前已附加能力的数量。</para>
	/// </summary>
	public int Count => _capabilities.Count;

	internal ModelCapabilitySet(AbstractModel owner)
	{
		Owner = owner;
		_readOnlyCapabilities = _capabilities.AsReadOnly();
	}

	internal IModelCapability[] GetAttachedSnapshot()
	{
		return _attachedSnapshot ?? (_attachedSnapshot = _capabilities.ToArray());
	}

	internal IModelCapability[] GetOwnerHookCandidateSnapshot()
	{
		return _ownerHookCandidateSnapshot ?? (_ownerHookCandidateSnapshot = _capabilities.Where((IModelCapability capability) => capability is IModelCapabilityHookListener modelCapabilityHookListener && modelCapabilityHookListener is AbstractModel).ToArray());
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Applies a capability, optionally merging it with an existing capability.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         应用能力，并可选择将其与已有能力合并。
	///     </para>
	/// </summary>
	public IModelCapability? Apply(IModelCapability incoming, ApplyModelCapabilityOptions options = default(ApplyModelCapabilityOptions))
	{
		ArgumentNullException.ThrowIfNull(incoming, "incoming");
		if (options.AllowMerge)
		{
			for (int i = 0; i < _capabilities.Count; i++)
			{
				IModelCapability modelCapability = _capabilities[i];
				if (modelCapability is IModelCapabilityMergeHandler modelCapabilityMergeHandler && (options.UseSubtractiveMerge ? modelCapabilityMergeHandler.TrySubtractiveMergeWith(incoming, options, out IModelCapability merged) : modelCapabilityMergeHandler.TryMergeWith(incoming, options, out merged)))
				{
					if (merged == modelCapability)
					{
						MarkDynamicVarsJustUpgraded(modelCapability, options);
						MarkDirty();
						return modelCapability;
					}
					if (merged != null)
					{
						EnsureCanAttach(merged);
					}
					string text = (_defaultCapabilities.Remove(modelCapability) ? modelCapability.CapabilityId : null);
					modelCapability.Detach();
					if (merged == null)
					{
						_capabilities.RemoveAt(i);
						InvalidateAttachedSnapshot();
						MarkDirty();
						return null;
					}
					_capabilities[i] = merged;
					InvalidateAttachedSnapshot();
					if (text != null && string.Equals(merged.CapabilityId, text, StringComparison.Ordinal))
					{
						_defaultCapabilities.Add(merged);
					}
					merged.Attach(Owner);
					MarkDynamicVarsJustUpgraded(merged, options);
					MarkDirty();
					return merged;
				}
			}
		}
		if (options.UseSubtractiveMerge)
		{
			return null;
		}
		EnsureCanAttach(incoming);
		_capabilities.Add(incoming);
		InvalidateAttachedSnapshot();
		incoming.Attach(Owner);
		MarkDynamicVarsJustUpgraded(incoming, options);
		MarkDirty();
		return incoming;
	}

	/// <summary>
	///     <para xml:lang="en">Applies a capability and returns the typed result.</para>
	///     <para xml:lang="zh-CN">应用能力并返回类型化结果。</para>
	/// </summary>
