	///     <para xml:lang="zh-CN">
	///         移除所有 <typeparamref name="TCapability" /> 类型的能力。分离回调抛出异常时，先前已处理的能力仍会
	///         保持移除状态。
	///     </para>
	/// </summary>
	public IReadOnlyList<TCapability> RemoveAll<TCapability>() where TCapability : class, IModelCapability
	{
		List<TCapability> list = new List<TCapability>();
		for (int num = _capabilities.Count - 1; num >= 0; num--)
		{
			if (_capabilities[num] is TCapability val)
			{
				val.Detach();
				_capabilities.RemoveAt(num);
				InvalidateAttachedSnapshot();
				_defaultCapabilities.Remove(val);
				list.Add(val);
			}
		}
		if (list.Count == 0)
		{
			return Array.Empty<TCapability>();
		}
		list.Reverse();
		MarkDirty();
		return list;
	}

