	/// <summary>
	///     <para xml:lang="en">
	///         Clears known capabilities and optionally clears unknown saved entries. If a detach callback throws,
	///         capabilities detached earlier remain present in the set until a later operation repairs the state.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         清除已知能力，并可选择同时清除未知的保存条目。分离回调抛出异常时，先前已完成分离的能力仍会
	///         留在集合中，直到后续操作修复该状态。
	///     </para>
	/// </summary>
	public void Clear(UnknownModelCapabilityPolicy unknownPolicy = UnknownModelCapabilityPolicy.Preserve)
	{
		if (_capabilities.Count == 0 && (unknownPolicy == UnknownModelCapabilityPolicy.Preserve || _unknownEntries.Count == 0))
		{
			return;
		}
		foreach (IModelCapability capability in _capabilities)
		{
			capability.Detach();
		}
		_capabilities.Clear();
		InvalidateAttachedSnapshot();
		_defaultCapabilities.Clear();
		if (unknownPolicy == UnknownModelCapabilityPolicy.Remove)
		{
			_unknownEntries.Clear();
		}
		MarkDirty();
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Replaces all known capabilities with <paramref name="capabilities" />. The operation is not
	///         transactional; a detach or attach callback failure can leave a partially replaced set.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         使用 <paramref name="capabilities" /> 替换所有已知能力。此操作不具备事务性；分离或附加回调失败
	///         时，集合可能处于只完成部分替换的状态。
	///     </para>
	/// </summary>
	public void ReplaceAll(IEnumerable<IModelCapability> capabilities, UnknownModelCapabilityPolicy unknownPolicy = UnknownModelCapabilityPolicy.Preserve)
	{
		ArgumentNullException.ThrowIfNull(capabilities, "capabilities");
		IModelCapability[] array = capabilities.ToArray();
		if (array.Any((IModelCapability modelCapability2) => modelCapability2 == null))
		{
			throw new ArgumentException("Capability collection cannot contain null entries.", "capabilities");
		}
		if (array.Distinct(ReferenceEqualityComparer.Instance).Count() != array.Length)
		{
			throw new ArgumentException("Capability collection cannot contain the same instance more than once.", "capabilities");
		}
		IModelCapability[] array2 = array;
		foreach (IModelCapability capability in array2)
		{
			EnsureCanAttach(capability, allowCurrentAttachment: true);
		}
		foreach (IModelCapability capability2 in _capabilities)
		{
			capability2.Detach();
		}
		_capabilities.Clear();
		InvalidateAttachedSnapshot();
		_defaultCapabilities.Clear();
		if (unknownPolicy == UnknownModelCapabilityPolicy.Remove)
		{
			_unknownEntries.Clear();
		}
		array2 = array;
		foreach (IModelCapability modelCapability in array2)
		{
			_capabilities.Add(modelCapability);
			InvalidateAttachedSnapshot();
			modelCapability.Attach(Owner);
		}
		MarkDirty();
	}

