	{
		if (document != null)
		{
			LoadDocument(document, CreateCurrentCapabilityLoadState());
		}
	}

	private void LoadDocument(ModelCapabilitySaveDocument? document, CapabilityLoadState loadState)
	{
		foreach (IModelCapability capability in _capabilities)
		{
			capability.Detach(isInternal: true);
		}
		_capabilities.Clear();
		InvalidateAttachedSnapshot();
		_defaultCapabilities.Clear();
		_unknownEntries.Clear();
		IsDirty = false;
		if (document == null)
		{
			AddMissingCapabilities(loadState);
		}
		else
		{
			LoadDocumentEntries(document, loadState);
		}
	}

	private void LoadDocumentEntries(ModelCapabilitySaveDocument document, CapabilityLoadState loadState)
	{
		foreach (ModelCapabilitySaveEntry capability2 in document.Capabilities)
		{
			CapabilityLoadItem item;
			IModelCapability capability;
			if (string.IsNullOrWhiteSpace(capability2.Id))
			{
				_unknownEntries.Add(CloneEntry(capability2));
			}
			else if (loadState.TryTake(capability2.Id, out item))
			{
				LoadCapabilityState(item.Capability, capability2);
				AddLoadedCapability(item);
				NotifyCapabilityLoadedFromSave(item.Capability);
			}
			else if (!ModelCapabilityRegistry.TryCreate(capability2.Id, out capability))
			{
				_unknownEntries.Add(CloneEntry(capability2));
			}
			else
			{
				LoadCapabilityState(capability, capability2);
				_capabilities.Add(capability);
				InvalidateAttachedSnapshot();
				capability.Attach(Owner, isInternal: true);
				NotifyCapabilityLoadedFromSave(capability);
			}
		}
		AddMissingCapabilities(loadState);
	}

	internal ModelCapabilitySaveDocument? Save()
	{
		if (_capabilities.Count == 0 && _unknownEntries.Count == 0 && !IsDirty)
		{
			return null;
		}
		ModelCapabilitySaveDocument modelCapabilitySaveDocument = new ModelCapabilitySaveDocument();
		modelCapabilitySaveDocument.Capabilities.AddRange(_unknownEntries.Select(CloneEntry));
		foreach (IModelCapability capability in _capabilities)
		{
			IModelCapabilityJsonState modelCapabilityJsonState = capability as IModelCapabilityJsonState;
			modelCapabilitySaveDocument.Capabilities.Add(new ModelCapabilitySaveEntry
			{
				Id = capability.CapabilityId,
				Schema = (modelCapabilityJsonState?.SchemaVersion ?? 1),
				Data = modelCapabilityJsonState?.SaveState()?.DeepClone()
			});
		}
		return modelCapabilitySaveDocument;
	}

	internal void CopyTo(ModelCapabilitySet target)
	{
		foreach (IModelCapability capability in target._capabilities)
		{
			capability.Detach(isInternal: true);
		}
		target._capabilities.Clear();
		target.InvalidateAttachedSnapshot();
		target._defaultCapabilities.Clear();
		target._unknownEntries.Clear();
		target._unknownEntries.AddRange(_unknownEntries.Select(CloneEntry));
		target.IsDirty = false;
		foreach (IModelCapability capability2 in _capabilities)
		{
			IModelCapability modelCapability = ((capability2 is IModelCapabilityCloneHandler modelCapabilityCloneHandler) ? modelCapabilityCloneHandler.CloneFor(target.Owner) : CloneThroughSave(capability2, target.Owner));
			target._capabilities.Add(modelCapability);
			target.InvalidateAttachedSnapshot();
			if (_defaultCapabilities.Contains(capability2))
			{
				target._defaultCapabilities.Add(modelCapability);
			}
			if (modelCapability.Owner != target.Owner)
			{
				modelCapability.Attach(target.Owner, isInternal: true);
			}
			if (modelCapability is IModelCapabilityCloneNotification modelCapabilityCloneNotification)
			{
				modelCapabilityCloneNotification.AfterOwnerCloned(Owner, target.Owner, capability2);
			}
		}
		if (IsDirty || _unknownEntries.Count > 0 || _capabilities.Any((IModelCapability capability) => !_defaultCapabilities.Contains(capability)))
		{
			target.MarkDirty();
		}
	}

	private CapabilityLoadState CreateDefaultCapabilityLoadState()
	{
		CapabilityLoadState capabilityLoadState = new CapabilityLoadState();
		foreach (IModelCapability item in ModelCapabilityDefaults.Create(Owner))
		{
			capabilityLoadState.Add(item, isDefault: true);
		}
		return capabilityLoadState;
	}

	private CapabilityLoadState CreateCurrentCapabilityLoadState()
	{
		CapabilityLoadState capabilityLoadState = new CapabilityLoadState();
		foreach (IModelCapability capability in _capabilities)
		{
			capabilityLoadState.Add(capability, _defaultCapabilities.Contains(capability));
		}
		return capabilityLoadState;
	}

	private void AddLoadedCapability(CapabilityLoadItem item)
	{
		_capabilities.Add(item.Capability);
		InvalidateAttachedSnapshot();
		if (item.IsDefault)
		{
			_defaultCapabilities.Add(item.Capability);
		}
		item.Capability.Attach(Owner, isInternal: true);
	}

	private void AddMissingCapabilities(CapabilityLoadState loadState)
	{
		foreach (CapabilityLoadItem item in loadState.TakeRemaining())
		{
			AddLoadedCapability(item);
		}
	}

	private static void LoadCapabilityState(IModelCapability capability, ModelCapabilitySaveEntry entry)
	{
		if (capability is IModelCapabilityJsonState modelCapabilityJsonState)
		{
			modelCapabilityJsonState.LoadState(entry.Data?.DeepClone(), entry.Schema);
		}
	}

	private void NotifyCapabilityLoadedFromSave(IModelCapability capability)
	{
		if (!(capability is ModelCapability modelCapability) || capability.Owner != Owner)
		{
			return;
		}
		try
		{
			modelCapability.NotifyLoadedFromSave();
		}
		catch (Exception exception)
		{
			ModelCapabilityDiagnostics.WarnFailure("model-capability-load", Owner, capability, exception);
		}
	}

	internal void MarkDirtyFromHost()
	{
		IsDirty = true;
	}

	private IModelCapability? InsertRelativeTo<TExisting>(IModelCapability capability, bool after, MissingModelCapabilityAnchorPolicy missingAnchorPolicy) where TExisting : class, IModelCapability
	{
		ArgumentNullException.ThrowIfNull(capability, "capability");
		int num = _capabilities.FindIndex((IModelCapability existing) => existing is TExisting);
		if (num >= 0)
		{
			return Insert(after ? (num + 1) : num, capability);
		}
		return missingAnchorPolicy switch
		{
			MissingModelCapabilityAnchorPolicy.Append => Insert(_capabilities.Count, capability), 
			MissingModelCapabilityAnchorPolicy.Prepend => Insert(0, capability), 
			MissingModelCapabilityAnchorPolicy.Skip => null, 
			MissingModelCapabilityAnchorPolicy.Throw => throw new InvalidOperationException($"Cannot find capability anchor '{typeof(TExisting).FullName}' on model '{Owner.Id}'."), 
			_ => throw new ArgumentOutOfRangeException("missingAnchorPolicy", missingAnchorPolicy, "Unknown missing anchor policy."), 
		};
	}

	private static bool CapabilityHasSavedState(IModelCapability capability)
	{
		if (capability is IModelCapabilityJsonState modelCapabilityJsonState)
		{
			return modelCapabilityJsonState.SaveState() != null;
		}
		return false;
	}

	private void InvalidateAttachedSnapshot()
	{
		_attachedSnapshot = null;
		_ownerHookCandidateSnapshot = null;
		ModelCapabilityHookListeners.InvalidateOwnerHookCapabilityCache(Owner);
	}

	private static void MarkDynamicVarsJustUpgraded(IModelCapability capability, ApplyModelCapabilityOptions options)
	{
		if (options.IsUpgrade && capability is ModelCapability modelCapability)
		{
			modelCapability.MarkDynamicVarsJustUpgraded();
		}
	}

	private static IModelCapability CloneThroughSave(IModelCapability capability, AbstractModel clonedOwner)
	{
		if (!ModelCapabilityRegistry.TryCreate(capability.CapabilityId, out IModelCapability capability2))
		{
			throw new InvalidOperationException("Cannot clone unknown model capability '" + capability.CapabilityId + "'.");
		}
		if (capability is IModelCapabilityJsonState modelCapabilityJsonState && capability2 is IModelCapabilityJsonState modelCapabilityJsonState2)
		{
			modelCapabilityJsonState2.LoadState(modelCapabilityJsonState.SaveState()?.DeepClone(), modelCapabilityJsonState.SchemaVersion);
		}
		capability2.Attach(clonedOwner, isInternal: true);
		return capability2;
	}

	private static ModelCapabilitySaveEntry CloneEntry(ModelCapabilitySaveEntry entry)
	{
		return new ModelCapabilitySaveEntry
		{
			Id = entry.Id,
			Schema = entry.Schema,
			Data = entry.Data?.DeepClone()
		};
	}

	private void EnsureCanAttach(IModelCapability capability, bool allowCurrentAttachment = false)
	{
		if (capability.Owner == null || (allowCurrentAttachment && capability.Owner == Owner && _capabilities.Any((IModelCapability existing) => existing == capability)))
		{
			return;
		}
		throw new InvalidOperationException($"Capability '{capability.CapabilityId}' is already attached to model '{capability.Owner.Id}'.");
	}
}
