using System;
using System.Threading;
using MegaCrit.Sts2.Core.Models;
using STS2RitsuLib.Utils;

namespace STS2RitsuLib.Models.Capabilities;

/// <summary>
///     <para xml:lang="en">Entry point for model capability hosts.</para>
///     <para xml:lang="zh-CN">模型能力宿主的入口。</para>
/// </summary>
public static class ModelCapabilities
{
	private const string SavedDataKey = "model_capabilities";

	private static readonly Lock InitializationLock = new Lock();

	private static readonly ModelSavedDataSlotKey SavedDataSlotKey = new ModelSavedDataSlotKey("com.ritsukage.sts2-RitsuLib", "model_capabilities");

	private static readonly AttachedState<AbstractModel, ModelCapabilitySet> Collections = new AttachedState<AbstractModel, ModelCapabilitySet>((Func<ModelCapabilitySet>)null);

	internal static bool IsInitialized { get; private set; }

	/// <summary>
	///     <para xml:lang="en">Initializes the built-in persistence slot for model capabilities.</para>
	///     <para xml:lang="zh-CN">初始化模型能力的内置持久化槽位。</para>
	/// </summary>
	public static void EnsureInitialized()
	{
		using (InitializationLock.EnterScope())
		{
			if (!IsInitialized)
			{
				ModelSavedDataStore.For("com.ritsukage.sts2-RitsuLib").RegisterComputed<AbstractModel, ModelCapabilitySaveDocument>("model_capabilities", (Func<AbstractModel, ModelCapabilitySaveDocument?>)Export, (Action<AbstractModel, ModelCapabilitySaveDocument?>)Import, (Func<ModelCapabilitySaveDocument>?)(() => new ModelCapabilitySaveDocument()), new ModelSavedDataOptions
				{
					ClonePolicy = ModelSavedDataClonePolicy.Copy,
					WritePolicy = ModelSavedDataWritePolicy.AlwaysWhenPresent
				});
				IsInitialized = true;
			}
		}
	}

	/// <summary>
	///     <para xml:lang="en">Gets the capability set for <paramref name="model" />.</para>
	///     <para xml:lang="zh-CN">获取 <paramref name="model" /> 的能力集合。</para>
	/// </summary>
	public static ModelCapabilitySet Get(AbstractModel model)
	{
		ArgumentNullException.ThrowIfNull(model, "model");
		return Collections.GetOrAdd(model, (Func<AbstractModel, ModelCapabilitySet>)CreateCollection);
	}

	/// <summary>
	///     <para xml:lang="en">Attempts to get an existing capability set without creating one.</para>
	///     <para xml:lang="zh-CN">尝试获取已有能力集合，但不创建新集合。</para>
	/// </summary>
	public static bool TryGet(AbstractModel model, out ModelCapabilitySet collection)
	{
		ArgumentNullException.ThrowIfNull(model, "model");
		return Collections.TryGetValue(model, ref collection);
	}

	internal static void MarkDirty(AbstractModel model)
	{
		ModelCapabilitySet modelCapabilitySet = default(ModelCapabilitySet);
		if (Collections.TryGetValue(model, ref modelCapabilitySet))
		{
			modelCapabilitySet.MarkDirtyFromHost();
		}
		MarkSavedDataDirty(model);
	}

	internal static void MarkSavedDataDirty(AbstractModel model)
	{
		if (!IsInitialized)
		{
			throw new InvalidOperationException("ModelCapabilities persistence has not been registered. Register a model capability or default capability modifier during mod initialization before mutating model capabilities.");
		}
		ModelSavedDataRuntime.GetBag(model).Set(SavedDataSlotKey, new ModelCapabilitySaveDocument());
	}

	internal static void NotifyCloned(AbstractModel prototype, AbstractModel clone)
	{
		if (TryGet(prototype, out ModelCapabilitySet collection))
		{
			ModelCapabilitySet target = Get(clone);
			collection.CopyTo(target);
		}
	}

	private static ModelCapabilitySet CreateCollection(AbstractModel model)
	{
		ModelCapabilitySet modelCapabilitySet = new ModelCapabilitySet(model);
		modelCapabilitySet.Load(null);
		if (IsInitialized)
		{
			ModelSavedDataRuntime.GetBag(model).Set(SavedDataSlotKey, new ModelCapabilitySaveDocument(), dirty: false);
		}
		return modelCapabilitySet;
	}

	private static ModelCapabilitySaveDocument? Export(AbstractModel model)
	{
		if (!TryGet(model, out ModelCapabilitySet collection))
		{
			if (!ModelCapabilityDefaults.HasDefaultCapabilitySource(model))
			{
				return null;
			}
			collection = Get(model);
		}
		if (!collection.ShouldSave())
		{
			return null;
		}
		return collection.Save();
	}

	private static void Import(AbstractModel model, ModelCapabilitySaveDocument? document)
	{
		if (!ModelCapabilityUpgradeReplayContext.TryDeferCardCapabilityImport(model, document))
		{
			ImportImmediate(model, document);
		}
	}

	internal static void ImportImmediate(AbstractModel model, ModelCapabilitySaveDocument? document)
	{
		Get(model).Load(document);
	}
